from enum import Enum


class TaskStatus(Enum):
    PENDING = "pending"
    READY = "ready"
    RUNNING = "running"
    COMPLETED = "completed"
    FAILED = "failed"
    BLOCKED = "blocked"


class ValidationErrorType(Enum):
    CYCLE_DETECTED = "cycle_detected"
    DUPLICATE_TASK = "duplicate_task"
    MISSING_DEPENDENCY = "missing_dependency"
    SELF_LOOP = "self_loop"
    EMPTY_GRAPH = "empty_graph"
    INVALID_DURATION = "invalid_duration"
    ORPHAN_TASK = "orphan_task"


@dataclass
class ValidationError:
    error_type: ValidationErrorType
    message: str
    task_ids: List[str] = field(default_factory=list)
    cycle_path: List[str] = field(default_factory=list)
    severity: str = "critical"  # critical, warning, info

    def to_dict(self) -> dict:
        return {
            "error_type": self.error_type.value,
            "message": self.message,
            "task_ids": self.task_ids,
            "cycle_path": self.cycle_path,
            "severity": self.severity,
        }


@dataclass
class Task:
    task_id: str
    name: str
    agent: str
    dependencies: List[str] = field(default_factory=list)
    estimated_duration: float = 1.0  # in seconds
    priority: int = 0
    metadata: dict = field(default_factory=dict)

    def to_dict(self) -> dict:
        return {
            "task_id": self.task_id,
            "name": self.name,
            "agent": self.agent,
            "dependencies": list(self.dependencies),
            "estimated_duration": self.estimated_duration,
            "priority": self.priority,
            "metadata": dict(self.metadata),
        }


@dataclass
class CriticalPathResult:
    path: List[str]
    total_duration: float
    task_details: List[dict]

    def to_dict(self) -> dict:
        return {
            "path": self.path,
            "total_duration": self.total_duration,
            "task_details": self.task_details,
        }


@dataclass
class ValidationResult:
    valid: bool
    errors: List[ValidationError] = field(default_factory=list)
    warnings: List[ValidationError] = field(default_factory=list)
    critical_path: Optional[CriticalPathResult] = None
    topological_order: List[str] = field(default_factory=list)
    parallelism_estimate: int = 0
    total_estimated_duration: float = 0.0
    task_count: int = 0
    edge_count: int = 0

    def to_dict(self) -> dict:
        return {
            "valid": self.valid,
            "errors": [e.to_dict() for e in self.errors],
            "warnings": [w.to_dict() for w in self.warnings],
            "critical_path": self.critical_path.to_dict() if self.critical_path else None,
            "topological_order": self.topological_order,
            "parallelism_estimate": self.parallelism_estimate,
            "total_estimated_duration": self.total_estimated_duration,
            "task_count": self.task_count,
            "edge_count": self.edge_count,
        }


class DAGValidator:
    """
    Validates a DAG of tasks before execution.
    Detects cycles, computes critical path, and provides scheduling insights.
    """

    def __init__(self):
        self.tasks: Dict[str, Task] = {}
        self.adjacency: Dict[str, List[str]] = defaultdict(list)
        self.reverse_adjacency: Dict[str, List[str]] = defaultdict(list)
        self.in_degree: Dict[str, int] = defaultdict(int)

    def add_task(self, task: Task) -> None:
        """Add a task to the validator's internal graph."""
        self.tasks[task.task_id] = task

    def build_graph(self) -> None:
        """Build adjacency list and in-degree map from tasks."""
        self.adjacency = defaultdict(list)
        self.reverse_adjacency = defaultdict(list)
        self.in_degree = defaultdict(int)

        for task_id, task in self.tasks.items():
            self.in_degree.setdefault(task_id, 0)
            for dep in task.dependencies:
                self.adjacency[dep].append(task_id)
                self.reverse_adjacency[task_id].append(dep)
                self.in_degree[task_id] += 1

    def detect_cycles(self) -> List[ValidationError]:
        """
        Detect cycles using DFS with coloring (white/gray/black).
        Returns list of errors, each containing the cycle path.
        """
        errors: List[ValidationError] = []
        WHITE, GRAY, BLACK = 0, 1, 2
        color: Dict[str, int] = {tid: WHITE for tid in self.tasks}
        parent: Dict[str, Optional[str]] = {tid: None for tid in self.tasks}

        def dfs(node: str) -> List[List[str]]:
            found_cycles = []
            color[node] = GRAY
            for neighbor in self.adjacency[node]:
                if color[neighbor] == GRAY:
                    # Found a back edge — extract cycle
                    cycle = [neighbor]
                    current = node
                    while current is not None and current != neighbor:
                        cycle.append(current)
                        current = parent[current]
                    cycle.append(neighbor)
                    cycle.reverse()
                    found_cycles.append(cycle)
                elif color[neighbor] == WHITE:
                    parent[neighbor] = node
                    found_cycles.extend(dfs(neighbor))
            color[node] = BLACK
            return found_cycles

        for tid in sorted(self.tasks.keys()):
            if color[tid] == WHITE:
                cycles = dfs(tid)
                for cycle in cycles:
                    errors.append(ValidationError(
                        error_type=ValidationErrorType.CYCLE_DETECTED,
                        message=f"Cycle detected: {' -> '.join(cycle)}",
                        task_ids=list(set(cycle)),
                        cycle_path=cycle,
                        severity="critical",
                    ))

        return errors

    def topological_sort(self) -> Tuple[Optional[List[str]], List[ValidationError]]:
        """
        Kahn's algorithm for topological sorting.
        Returns (order, errors). If cycles exist, order is None.
        """
        errors: List[ValidationError] = []
        in_degree = dict(self.in_degree)
        queue = deque()

        for tid in self.tasks:
            if in_degree.get(tid, 0) == 0:
                queue.append(tid)

        order: List[str] = []
        while queue:
            node = queue.popleft()
            order.append(node)
            for neighbor in self.adjacency[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        if len(order) != len(self.tasks):
            remaining = set(self.tasks.keys()) - set(order)
            errors.append(ValidationError(
                error_type=ValidationErrorType.CYCLE_DETECTED,
                message=f"Topological sort incomplete; {len(remaining)} tasks in cycles: {sorted(remaining)}",
                task_ids=sorted(remaining),
                severity="critical",
            ))
            return None, errors

        return order, errors

    def compute_critical_path(self, topo_order: List[str]) -> CriticalPathResult:
        """
        Compute the critical path (longest path by duration) using DP on topological order.
        """
        if not topo_order:
            return CriticalPathResult(path=[], total_duration=0.0, task_details=[])

        # earliest_finish[task] = max(earliest_finish[dep]) + duration[task]
        earliest_finish: Dict[str, float] = {}
        earliest_start: Dict[str, float] = {}
        predecessor: Dict[str, Optional[str]] = {}

        for tid in topo_order:
            task = self.tasks[tid]
            es = 0.0
            pred = None
            for dep in self.reverse_adjacency[tid]:
                if dep in earliest_finish:
                    if earliest_finish[dep] > es:
                        es = earliest_finish[dep]
                        pred = dep
            earliest_start[tid] = es
            earliest_finish[tid] = es + task.estimated_duration
            predecessor[tid] = pred

        # Find the task with the maximum earliest finish
        end_task = max(earliest_finish, key=lambda t: earliest_finish[t])
        total_duration = earliest_finish[end_task]

        # Reconstruct path
        path: List[str] = []
        current: Optional[str] = end_task
        while current is not None:
            path.append(current)
            current = predecessor[current]
        path.reverse()

        task_details = []
        for tid in path:
            task = self.tasks[tid]
            task_details.append({
                "task_id": tid,
                "name": task.name,
                "agent": task.agent,
                "estimated_duration": task.estimated_duration,
                "earliest_start": earliest_start[tid],
                "earliest_finish": earliest_finish[tid],
            })

        return CriticalPathResult(
            path=path,
            total_duration=total_duration,
            task_details=task_details,
        )

    def compute_parallelism(self, topo_order: List[str]) -> int:
        """
        Estimate maximum parallelism (width of the DAG).
        Uses a level-based approach.
        """
        if not topo_order:
            return 0

        level: Dict[str, int] = {}
        for tid in topo_order:
            if not self.reverse_adjacency[tid]:
                level[tid] = 0
            else:
                level[tid] = max(
                    (level[dep] for dep in self.reverse_adjacency[tid] if dep in level),
                    default=0,
                ) + 1

        level_counts: Dict[int, int] = defaultdict(int)
        for lvl in level.values():
            level_counts[lvl] += 1

        return max(level_counts.values()) if level_counts else 0

    def find_orphans(self) -> List[ValidationError]:
        """Find tasks with no dependencies and no dependents (disconnected)."""
        warnings: List[ValidationError] = []
        for tid in self.tasks:
            has_incoming = len(self.reverse_adjacency[tid]) > 0
            has_outgoing = len(self.adjacency[tid]) > 0
            if not has_incoming and not has_outgoing and len(self.tasks) > 1:
                warnings.append(ValidationError(
                    error_type=ValidationErrorType.ORPHAN_TASK,
                    message=f"Task '{tid}' ({self.tasks[tid].name}) is disconnected from the graph",
                    task_ids=[tid],
                    severity="warning",
                ))
        return warnings

    def validate(self) -> ValidationResult:
        """
        Full validation: structural checks, cycle detection, critical path.
        """
        errors: List[ValidationError] = []
        warnings: List[ValidationError] = []

        # Check empty graph
        if not self.tasks:
            errors.append(ValidationError(
                error_type=ValidationErrorType.EMPTY_GRAPH,
                message="No tasks in the graph",
                severity="critical",
            ))
            return ValidationResult(valid=False, errors=errors)

        # Check for self-loops
        for tid, task in self.tasks.items():
            if tid in task.dependencies:
                errors.append(ValidationError(
                    error_type=ValidationErrorType.SELF_LOOP,
                    message=f"Task '{tid}' depends on itself",
                    task_ids=[tid],
                    severity="critical",
                ))

        # Check for missing dependencies
        for tid, task in self.tasks.items():
            for dep in task.dependencies:
                if dep not in self.tasks:
                    errors.append(ValidationError(
                        error_type=ValidationErrorType.MISSING_DEPENDENCY,
                        message=f"Task '{tid}' depends on non-existent task '{dep}'",
                        task_ids=[tid, dep],
                        severity="critical",
                    ))

        # Check for invalid durations
        for tid, task in self.tasks.items():
            if task.estimated_duration <= 0:
                errors.append(ValidationError(
                    error_type=ValidationErrorType.INVALID_DURATION,
                    message=f"Task '{tid}' has invalid duration: {task.estimated_duration}",
                    task_ids=[tid],
                    severity="critical",
                ))

        if errors:
            return ValidationResult(valid=False, errors=errors)

        # Build graph
        self.build_graph()

        # Detect cycles
        cycle_errors = self.detect_cycles()
        errors.extend(cycle_errors)

        if cycle_errors:
            return ValidationResult(valid=False, errors=errors)

        # Topological sort
        topo_order, topo_errors = self.topological_sort()
        if topo_errors:
            errors.extend(topo_errors)
            return ValidationResult(valid=False, errors=errors)

        # Orphan warnings
        warnings.extend(self.find_orphans())

        # Critical path
        critical_path = self.compute_critical_path(topo_order)

        # Parallelism
        parallelism = self.compute_parallelism(topo_order)

        # Total duration (sum of all task durations)
        total_duration = sum(t.estimated_duration for t in self.tasks.values())

        # Edge count
        edge_count = sum(len(t.dependencies) for t in self.tasks.values())

        return ValidationResult(
            valid=True,
            errors=errors,
            warnings=warnings,
            critical_path=critical_path,
            topological_order=topo_order,
            parallelism_estimate=parallelism,
            total_estimated_duration=total_duration,
            task_count=len(self.tasks),
            edge_count=edge_count,
        )


class TaskRegistry:
    """
    Task registry with pre-validation on creation.
    Simulates the A2A Mesh task creation flow with DAG pre-validation.
    """

    def __init__(self):
        self.validator = DAGValidator()
        self.tasks: Dict[str, Task] = {}
        self.validation_history: List[dict] = []

    def create_task(
        self,
        name: str,
        agent: str,
        dependencies: Optional[List[str]] = None,
        estimated_duration: float = 1.0,
        priority: int = 0,
        metadata: Optional[dict] = None,
    ) -> Tuple[Optional[str], Optional[ValidationResult]]:
        """
        Create a task with pre-validation. Returns (task_id, validation_result).
        If validation fails, task_id is None.
        """
        task_id = f"task_{uuid.uuid4().hex[:12]}"
        task = Task(
            task_id=task_id,
            name=name,
            agent=agent,
            dependencies=dependencies or [],
            estimated_duration=estimated_duration,
            priority=priority,
            metadata=metadata or {},
        )

        # Temporarily add and validate
        self.validator.add_task(task)
        result = self.validator.validate()

        if not result.valid:
            # Remove the task — validation failed
            del self.validator.tasks[task_id]
            self.validator.build_graph()
            self.validation_history.append({
                "timestamp": time.time(),
                "action": "create_rejected",
                "task_id": task_id,
                "task_name": name,
                "validation": result.to_dict(),
            })
            return None, result

        # Accept the task
        self.tasks[task_id] = task
        self.validation_history.append({
            "timestamp": time.time(),
            "action": "create_accepted",
            "task_id": task_id,
            "task_name": name,
            "validation": result.to_dict(),
        })
        return task_id, result

    def get_validation_report(self) -> dict:
        """Get the latest full validation report."""
        self.validator.build_graph()
        result = self.validator.validate()
        return result.to_dict()

    def get_execution_plan(self) -> dict:
        """Get an execution plan based on topological order and critical path."""
        self.validator.build_graph()
        result = self.validator.validate()
        if not result.valid:
            return {
                "valid": False,
                "errors": [e.to_dict() for e in result.errors],
                "plan": None,
            }

        # Build level-based execution waves
        levels: Dict[str, int] = {}
        for tid in result.topological_order:
            deps = self.validator.reverse_adjacency[tid]
            if not deps:
                levels[tid] = 0
            else:
                levels[tid] = max(levels[d] for d in deps if d in levels) + 1

        waves: Dict[int, List[str]] = defaultdict(list)
        for tid, lvl in levels.items():
            waves[lvl].append(tid)

        plan = []
        for lvl in sorted(waves.keys()):
            wave_tasks = []
            for tid in waves[lvl]:
                task = self.tasks[tid]
                wave_tasks.append({
                    "task_id": tid,
                    "name": task.name,
                    "agent": task.agent,
                    "duration": task.estimated_duration,
                })
            plan.append({
                "wave": lvl,
                "tasks": wave_tasks,
                "parallel_count": len(wave_tasks),
            })

        return {
            "valid": True,
            "plan": plan,
            "critical_path": result.critical_path.to_dict() if result.critical_path else None,
            "total_waves": len(plan),
            "max_parallelism": result.parallelism_estimate,
            "critical_path_duration": result.critical_path.total_duration if result.critical_path else 0,
        }


def demo_valid_dag():
    """Demo: a valid DAG with multiple parallel branches."""
    print("=" * 70)
    print("DEMO 1: Valid DAG with parallel branches")
    print("=" * 70)

    registry = TaskRegistry()

    tasks_to_create = [
        ("Fetch data", "fetcher", [], 2.0),
        ("Parse config", "parser", [], 1.0),
        ("Normalize data", "processor", ["task_0"], 3.0),  # will use actual IDs
        ("Validate schema", "validator", ["task_1"], 1.5),
        ("Merge results", "merger", [], 2.0),
        ("Generate report", "reporter", [], 4.0),
        ("Final aggregation", "aggregator", [], 1.0),
    ]

    # We need to create them in order and track IDs
    created_ids: List[str] = []

    # Create root tasks first
    tid0, r0 = registry.create_task("Fetch data", "fetcher", [], 2.0)
    created_ids.append(tid0)
    tid1, r1 = registry.create_task("Parse config", "parser", [], 1.0)
    created_ids.append(tid1)

    # Create dependent tasks
    tid2, r2 = registry.create_task("Normalize data", "processor", [tid0], 3.0)
    created_ids.append(tid2)
    tid3, r3 = registry.create_task("Validate schema", "validator", [tid1], 1.5)
    created_ids.append(tid3)

    tid4, r4 = registry.create_task("Merge results", "merger", [tid2, tid3], 2.0)
    created_ids.append(tid4)

    tid5, r5 = registry.create_task("Generate report", "reporter", [tid4], 4.0)
    created_ids.append(tid5)

    tid6, r6 = registry.create_task("Final aggregation", "aggregator", [tid5], 1.0)
    created_ids.append(tid6)

    print(f"\nCreated {len(created_ids)} tasks:")
    for tid in created_ids:
        task = registry.tasks[tid]
        print(f"  {tid}: {task.name} (agent={task.agent}, deps={task.dependencies}, dur={task.estimated_duration}s)")

    report = registry.get_validation_report()
    print(f"\nValidation: {'PASSED' if report['valid'] else 'FAILED'}")
    print(f"  Tasks: {report['task_count']}, Edges: {report['edge_count']}")
    print(f"  Max parallelism: {report['parallelism_estimate']}")
    print(f"  Total sequential duration: {report['total_estimated_duration']:.1f}s")

    if report['critical_path']:
        cp = report['critical_path']
        print(f"\n  Critical path ({cp['total_duration']:.1f}s):")
        for detail in cp['task_details']:
            print(f"    {detail['task_id']}: {detail['name']} "
                  f"[ES={detail['earliest_start']:.1f}, EF={detail['earliest_finish']:.1f}, "
                  f"dur={detail['estimated_duration']:.1f}s]")

    print(f"\n  Topological order: {report['topological_order']}")

    plan = registry.get_execution_plan()
    print(f"\n  Execution plan ({plan['total_waves']} waves):")
    for wave in plan['plan']:
        names = [f"{t['name']}({t['duration']:.1f}s)" for t in wave['tasks']]
        print(f"    Wave {wave['wave']}: {wave['parallel_count']} parallel -> {', '.join(names)}")

    return registry


def demo_cycle_detection():
    """Demo: cycle detection prevents task creation."""
    print("\n" + "=" * 70)
    print("DEMO 2: Cycle detection — task creation rejected")
    print("=" * 70)

    registry = TaskRegistry()

    tid_a, _ = registry.create_task("Task A", "agent1", [], 1.0)
    tid_b, _ = registry.create_task("Task B", "agent2", [tid_a], 1.0)
    tid_c, _ = registry.create_task("Task C", "agent3", [tid_b], 1.0)

    print(f"\nCreated: {tid_a} -> {tid_b} -> {tid_c}")

    # Now try to create a task that depends on C but is depended on by A
    # This would create a cycle: A -> B -> C -> D, and D -> A
    # We simulate by adding D that depends on C, then trying to make A depend on D
    tid_d, _ = registry.create_task("Task D", "agent4", [tid_c], 1.0)
    print(f"Created: {tid_d} (depends on {tid_c})")

    # Now try to add a task E that depends on D, and then modify A to depend on E
    # Actually, let's try to create a task that creates a cycle directly
    # We'll add a new task that depends on D, and then try to add a dependency
    # from A to that new task — but since we can't modify, let's create a cycle
    # by making a task that depends on D and also is a dependency of A

    # Simpler: create task E that depends on D, then try to create task F
    # that depends on E but also D depends on F (impossible via create)
    # Instead, let's directly test the validator with a cycle

    print("\n  Directly testing validator with a cycle:")
    v = DAGValidator()
    v.add_task(Task("x1", "X1", "a1", ["x3"], 1.0))
    v.add_task(Task("x2", "X2", "a2", ["x1"], 1.0))
    v.add_task(Task("x3", "X3", "a3", ["x2"], 1.0))
    v.build_graph()
    result = v.validate()
    print(f"  Valid: {result.valid}")
    for err in result.errors:
        print(f"  ERROR: {err.message}")
        print(f"  Cycle path: {' -> '.join(err.cycle_path)}")


